fn safe_sqrt(x: Float64) -> Result[Float64, Str] {
  if x < 0.0 { return Err("negative sqrt"); }
  return Ok(math.sqrt(x));
}

fn safe_reciprocal(x: Float64) -> Result[Float64, Str] {
  if x == 0.0 { return Err("division by zero"); }
  return Ok(1.0 / x);
}

fn compute(x: Float64) -> Result[Float64, Str] {
  let root = safe_sqrt(x)?;
  let recip = safe_reciprocal(root)?;
  return Ok(recip);
}

fn main() -> Int {
  match compute(4.0) {
    Ok(val) => { return (val * 10.0) as Int; }
    Err(_) => { return 0; }
  }
}
